-- rule twin_assemblies (same_signature): parameterized; p1 bigint
WITH e AS (SELECT t."parent_id" AS node, t."child_id" AS kid, sum(t."qty_per") AS qsum FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL GROUP BY t."parent_id", t."child_id"), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT n."part_id" AS member, s.sig, n."name" AS a1, n."unit" AS a2, n."part_class" AS a3 FROM s JOIN "sxc_rules"."part" n ON n."part_id" = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1, k.a2, k.a3)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(:p1 AS bigint);

-- rule twin_assemblies: view
CREATE OR REPLACE VIEW "sxc_out"."v_rule_twin_assemblies" AS
SELECT r.*, row_number() OVER (ORDER BY r."group_id" COLLATE "C" NULLS FIRST, r."member" COLLATE "C" NULLS FIRST) AS ord FROM (WITH e AS (SELECT t."parent_id" AS node, t."child_id" AS kid, sum(t."qty_per") AS qsum FROM "sxc_rules"."bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL GROUP BY t."parent_id", t."child_id"), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT n."part_id" AS member, s.sig, n."name" AS a1, n."unit" AS a2, n."part_class" AS a3 FROM s JOIN "sxc_rules"."part" n ON n."part_id" = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1, k.a2, k.a3)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(E'2' AS bigint)) r;

-- example twin_assemblies[0]: parameterized; 25 parameters
WITH "sxc_ex_part"("part_id", "name", "unit", "part_class") AS (VALUES (CAST(:p1 AS text), CAST(:p2 AS text), CAST(:p3 AS text), CAST(:p4 AS text)), (CAST(:p5 AS text), CAST(:p6 AS text), CAST(:p7 AS text), CAST(:p8 AS text)), (CAST(:p9 AS text), CAST(:p10 AS text), CAST(:p11 AS text), CAST(:p12 AS text))), "sxc_ex_bom_line"("parent_id", "child_id", "qty_per") AS (VALUES (CAST(:p13 AS text), CAST(:p14 AS text), CAST(:p15 AS numeric(18,6))), (CAST(:p16 AS text), CAST(:p17 AS text), CAST(:p18 AS numeric(18,6))), (CAST(:p19 AS text), CAST(:p20 AS text), CAST(:p21 AS numeric(18,6))), (CAST(:p22 AS text), CAST(:p23 AS text), CAST(:p24 AS numeric(18,6)))) SELECT * FROM (WITH e AS (SELECT t."parent_id" AS node, t."child_id" AS kid, sum(t."qty_per") AS qsum FROM "sxc_ex_bom_line" t WHERE t."parent_id" IS NOT NULL AND t."child_id" IS NOT NULL GROUP BY t."parent_id", t."child_id"), s AS (SELECT e.node, string_agg(encode(convert_to(e.kid, 'UTF8'), 'hex') || ':' || CAST(trim_scale(e.qsum) AS text), ',' ORDER BY e.kid COLLATE "C") AS sig FROM e GROUP BY e.node), k AS (SELECT n."part_id" AS member, s.sig, n."name" AS a1, n."unit" AS a2, n."part_class" AS a3 FROM s JOIN "sxc_ex_part" n ON n."part_id" = s.node), c AS (SELECT k.member, min(k.member COLLATE "C") OVER w AS group_id, count(*) OVER w AS members FROM k WINDOW w AS (PARTITION BY k.sig, k.a1, k.a2, k.a3)) SELECT c.group_id AS "group_id", c.member AS "member" FROM c WHERE c.members >= CAST(:p25 AS bigint)) r;
